<?php

declare(strict_types=1);

/**
 * Handler: users
 * Generated by CRUDify API — do not edit by hand.
 *
 * Routes:
 *   GET    /users             list (paginated, filterable)
 *   GET    /users/{id}        single record
 *   GET    /users/{id}/bookings   nested (user_id)
 *   POST   /users             create
 *   PUT    /users/{id}        update
 *   DELETE /users/{id}        delete
 */

function users_validate_insert(array $data): array
{
    $errors = [];
    if (!array_key_exists('name', $data) || $data['name'] === null || $data['name'] === '') {
        $errors['name'] = 'required';
    }
    if (!array_key_exists('email', $data) || $data['email'] === null || $data['email'] === '') {
        $errors['email'] = 'required';
    }
    return $errors;
}

function users_validate_update(array $data): array
{
    $errors = [];
    if (!array_key_exists('name', $data) || $data['name'] === null || $data['name'] === '') {
        $errors['name'] = 'required';
    }
    if (!array_key_exists('email', $data) || $data['email'] === null || $data['email'] === '') {
        $errors['email'] = 'required';
    }
    return $errors;
}

function users_handle(Request $req): void
{
    $db = DB::get();
    $id = $req->id();

    // GET /users/{id}/bookings[?filters]
    if ($req->method === 'GET' && $id !== null && $req->nested() === 'bookings') {
        $filters = array_diff_key($req->query, ['page' => 1, 'per_page' => 1]);
        $page    = max(1, (int)($req->query['page'] ?? 1));
        $perPage = min(100, (int)($req->query['per_page'] ?? 20));
        $offset  = ($page - 1) * $perPage;
        $where   = ['user_id = ?'];
        $params  = [$id];
        foreach ($filters as $col => $val) {
            $where[]  = "`{$col}` = ?";
            $params[] = $val;
        }
        $whereStr = implode(' AND ', $where);
        $count = DB::get()->prepare("SELECT COUNT(*) FROM `bookings` WHERE {$whereStr}");
        $count->execute($params);
        $stmt = DB::get()->prepare("SELECT * FROM `bookings` WHERE {$whereStr} LIMIT ? OFFSET ?");
        $stmt->execute([...$params, $perPage, $offset]);
        Response::ok([
            'data' => $stmt->fetchAll(),
            'meta' => ['page' => $page, 'per_page' => $perPage, 'total' => (int)$count->fetchColumn()],
        ]);
    }

    // GET /users/{id}  — single record
    if ($req->method === 'GET' && $id !== null && $req->nested() === null) {
        $stmt = $db->prepare("SELECT * FROM `users` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        $row = $stmt->fetch();
        if (!$row) Response::notFound('Users not found');
        Response::ok($row);
    }

    // GET /users  — list (filters + pagination)
    if ($req->method === 'GET' && $id === null) {
        $filters = array_diff_key($req->query, ['page' => 1, 'per_page' => 1]);
        $page    = max(1, (int)($req->query['page']     ?? 1));
        $perPage = min(100, (int)($req->query['per_page'] ?? 20));
        $offset  = ($page - 1) * $perPage;

        $where  = ['1=1'];
        $params = [];
        foreach ($filters as $col => $val) {
            $where[]  = "`{$col}` = ?";
            $params[] = $val;
        }
        $whereStr = implode(' AND ', $where);

        $count = $db->prepare("SELECT COUNT(*) FROM `users` WHERE {$whereStr}");
        $count->execute($params);

        $stmt = $db->prepare("SELECT * FROM `users` WHERE {$whereStr} LIMIT ? OFFSET ?");
        $stmt->execute([...$params, $perPage, $offset]);

        Response::ok([
            'data' => $stmt->fetchAll(),
            'meta' => [
                'page'     => $page,
                'per_page' => $perPage,
                'total'    => (int)$count->fetchColumn(),
            ],
        ]);
    }

    // POST /users  — create
    if ($req->method === 'POST' && $id === null) {
        $data   = $req->body;
        $errors = users_validate_insert($data);
        if ($errors) Response::unprocessable($errors);

        $values = array_map(fn($c) => $data[$c] ?? null, array (
  0 => 'name',
  1 => 'email',
));
        $stmt   = $db->prepare("INSERT INTO `users` (`name`, `email`) VALUES (?, ?)");
        $stmt->execute($values);

        $stmt = $db->prepare("SELECT * FROM `users` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$db->lastInsertId()]);
        Response::created($stmt->fetch());
    }

    // PUT /users/{id}  — update
    if ($req->method === 'PUT' && $id !== null) {
        $stmt = $db->prepare("SELECT 1 FROM `users` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        if (!$stmt->fetch()) Response::notFound('Users not found');

        $data   = $req->body;
        $errors = users_validate_update($data);
        if ($errors) Response::unprocessable($errors);

        $values   = array_map(fn($c) => $data[$c] ?? null, array (
  0 => 'name',
  1 => 'email',
));
        $values[] = $id;
        $stmt     = $db->prepare("UPDATE `users` SET `name` = ?, `email` = ? WHERE `id` = ?");
        $stmt->execute($values);

        $stmt = $db->prepare("SELECT * FROM `users` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        Response::ok($stmt->fetch());
    }

    // DELETE /users/{id}  — delete
    if ($req->method === 'DELETE' && $id !== null) {
        $stmt = $db->prepare("SELECT 1 FROM `users` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        if (!$stmt->fetch()) Response::notFound('Users not found');

        $stmt = $db->prepare("DELETE FROM `users` WHERE `id` = ?");
        $stmt->execute([$id]);
        Response::noContent();
    }

    Response::error('Method not allowed', 405);
}